test('balloons lean outward, trail acceleration, and settle with anchored strings',()=>{const model=createKart(0),pose={speed:20,steering:1,yawRate:1.5,drift:0,boost:0,vy:0};for(let i=0;i<45;i++)animateKart(model,pose,1/60,i/60);const motion=model.userData.balloonMotion[1];assert.ok(motion.x<-.6);assert.ok(motion.z<-.2);const turned=motion.x;animateKart(model,{...pose,steering:-1,yawRate:-1.5},1/60,.76);assert.ok(Math.abs(motion.x-turned)<.15,'turn reversal must not snap');for(let i=0;i<240;i++)animateKart(model,{...pose,speed:0,steering:0,yawRate:0},1/60,1+i/60);assert.ok(Math.abs(motion.x)<.2);assert.ok(Math.abs(motion.z)<.2);model.updateMatrixWorld(true);const line=model.getObjectByName('tether1') as T.Line,start=new T.Vector3().fromBufferAttribute(line.geometry.getAttribute('position'),0);assert.ok(start.distanceTo(model.getObjectByName('balloonAnchor1')!.getWorldPosition(new T.Vector3()))<1e-5);});
