test('quick fire and hop taps survive between simulation frames and are consumed once',()=>{const saved=globalThis.addEventListener,handlers=new Map<string,(e:any)=>void>();globalThis.addEventListener=((name:string,fn:any)=>{handlers.set(name,fn);}) as typeof addEventListener;try{const controls=new Controls();controls.active=true;for(const code of ['KeyE','Space']){handlers.get('keydown')!({code,repeat:false,preventDefault(){}});handlers.get('keyup')!({code});}const first=controls.read(0);assert.equal(first.fire,true);assert.equal(first.hop,true);assert.equal(controls.read(0).fire,false);assert.equal(controls.read(0).hop,false);handlers.get('keydown')!({code:'KeyE',repeat:false,preventDefault(){}});handlers.get('blur')!({});assert.equal(controls.read(0).fire,false);}finally{globalThis.addEventListener=saved;}});

test('spectator engine pitch and volume follow the same surviving kart as the camera',()=>{const s=createState({...config,bots:3});s.karts[0].balloons=0;s.karts[0].speed=20;s.karts[1].speed=0;const sound=new Sound(),freq:number[]=[],gain:number[]=[];sound.ctx={currentTime:0} as AudioContext;sound.engine={frequency:{setTargetAtTime:(v:number)=>freq.push(v)}} as unknown as OscillatorNode;sound.engineGain={gain:{setTargetAtTime:(v:number)=>gain.push(v)}} as unknown as GainNode;assert.equal(watchedKart(s,0).id,1);sound.update(watchedKart(s,0).speed,true);s.karts[1].speed=20;sound.update(watchedKart(s,0).speed,true);assert.ok(freq[1]>freq[0]);assert.ok(gain[1]>gain[0]);s.karts[1].speed=3;sound.update(watchedKart(s,0).speed,true);assert.ok(freq[2]<freq[1]);assert.ok(gain[2]<gain[1]);s.karts[1].balloons=0;assert.equal(watchedKart(s,0).id,2);sound.update(20,false);assert.equal(gain[3],0);});
