test('final balloon emits one elimination event while shields and repeat hits do not',()=>{const s=match(),k=s.karts[1];k.balloons=1;k.shield=1;damage(s,k,0);assert.equal(s.events.filter(e=>e.type==='eliminated').length,0);k.inv=0;damage(s,k,0);assert.equal(k.balloons,0);assert.equal(s.events.filter(e=>e.type==='eliminated').length,1);assert.equal(s.karts[0].kills,1);damage(s,k,0);assert.equal(s.events.filter(e=>e.type==='eliminated').length,1);});
test('elimination animation is finite, shrinks away, cleans up and respects reduced motion',()=>{const a=eliminationPose(0),b=eliminationPose(.55),c=eliminationPose(ELIMINATION_TIME);assert.equal(a.scale,1);assert.ok(b.rise>1&&b.spin>0&&b.scale<1);assert.equal(c.visible,false);const reduced=eliminationPose(.55,true);assert.equal(reduced.spin,0);assert.equal(reduced.rise,0);assert.ok(reduced.scale<1);for(const lowMotion of [false,true]){const fx=new BattleEffects(lowMotion);fx.spawn({id:1,type:'eliminated',player:0,x:2,y:0,z:3});assert.equal(fx.bursts.length,1);fx.update(.5);fx.traverse(o=>{assert.ok(Number.isFinite(o.position.x+o.position.y+o.position.z));});fx.update(1);assert.equal(fx.bursts.length,0);assert.equal(fx.children.length,0);}});
