test('spectator input edges respect separate couch keys, menu holds and assigned controllers',()=>{const saved=globalThis.addEventListener,pads=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const pad={index:2,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[0,0]};Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[null,null,pad]});try{const c=new Controls();c.readSpectator(0,false);c.readSpectator(1,false);c.keys.add('KeyD');assert.equal(c.readSpectator(0,true),1);assert.equal(c.readSpectator(0,true),0);assert.equal(c.readSpectator(1,true),0);c.keys.clear();c.keys.add('ArrowLeft');assert.equal(c.readSpectator(1,true),-1);c.keys.clear();c.readSpectator(0,false);c.keys.add('KeyA');c.readSpectator(0,false);assert.equal(c.readSpectator(0,true),0);c.keys.clear();c.readSpectator(0,true);c.pads[0]=2;pad.buttons[5].pressed=true;assert.equal(c.readSpectator(0,true),1);assert.equal(c.readSpectator(0,true),0);pad.buttons[5].pressed=false;c.readSpectator(0,true);c.padLocks.add(2);pad.buttons[4].pressed=true;assert.equal(c.readSpectator(0,true),0);}finally{globalThis.addEventListener=saved;if(pads)Object.defineProperty(navigator,'getGamepads',pads);else Reflect.deleteProperty(navigator,'getGamepads');}});

