test('new arenas are large, include safe navigation and Castle pits are actually open',()=>{for(const arena of ['castle','beach','stadium'] as const){assert.ok(arenaExtent(arena)>=120);const s=createState({...config,arena,bots:7});for(const p of nav(arena))assert.ok(p.y>=0);for(const k of s.karts)assert.ok(k.y>=0);}for(const p of LAVA_PITS){assert.ok(lavaAt(p.x,p.z));assert.equal(ground('castle',p.x*2,p.z*2),-40);}const s=match();s.config.arena='castle';const k=s.karts[0];k.x=LAVA_PITS[0].x*2;k.z=LAVA_PITS[0].z*2;k.y=0;for(let i=0;i<60;i++)drive(s,k,idle(),1/60);assert.equal(k.balloons,2);assert.ok(k.y>=0);assert.equal(k.x,0);assert.equal(k.z,0);});
function footballMatch(){const s=createState({...config,arena:'stadium'});s.phase='playing';s.karts.forEach((k,i)=>{k.bot=false;k.x=60+i*15;k.z=50;});return s;}
test('stadium goals trigger once, emit fireworks metadata and reset the ball at midfield',()=>{for(const sign of [-1,1]){const s=footballMatch(),b=s.ball!;b.z=sign*(PITCH.halfLength-.2);b.vz=sign*30;b.lastTouch=0;stepFootball(s,1/60);assert.equal(s.events.filter(e=>e.type==='goal').length,1);assert.ok(b.respawn>0);assert.equal(b.goals[sign>0?1:0],1);stepFootball(s,1);assert.equal(s.events.filter(e=>e.type==='goal').length,1);stepFootball(s,1.1);assert.equal(b.respawn,0);assert.equal(b.x,0);assert.equal(b.z,0);assert.equal(b.vx,0);assert.equal(b.vz,0);assert.equal(b.goals[sign>0?1:0],1);}});
test('the stadium ball can be rammed, rebounds at walls and does not score outside the mouth',()=>{const s=footballMatch(),b=s.ball!,k=s.karts[0];k.x=0;k.z=-2.5;k.angle=0;k.vz=k.speed=25;stepFootball(s,1/60);assert.ok(b.vz>20);assert.equal(b.lastTouch,0);k.x=80;k.z=80;b.x=125;b.vx=40;b.z=0;stepFootball(s,1/60);assert.ok(b.vx<0);b.x=35;b.z=PITCH.halfLength-.2;b.vz=40;stepFootball(s,1/60);assert.equal(b.goals[1],0);b.x=0;b.z=PITCH.halfLength-.2;b.y=15;b.vz=40;stepFootball(s,1/60);assert.equal(b.goals[1],0);});
