test('stadium has a tall populated bowl and fictional advertising without floor overlay planes',()=>{const details=new ArenaDetails('stadium');details.updateMatrixWorld(true);const bodies=details.getObjectByName('stadiumCrowdBodies') as T.InstancedMesh,heads=details.getObjectByName('stadiumCrowdHeads') as T.InstancedMesh;assert.ok(bodies.count>3000);assert.equal(bodies.count,heads.count);const matrix=new T.Matrix4(),position=new T.Vector3();let high=0;for(let i=0;i<heads.count;i++){heads.getMatrixAt(i,matrix);position.setFromMatrixPosition(matrix);high=Math.max(high,position.y);}assert.ok(high>28);assert.ok(details.getObjectByName('fictionalAdvertising'));let oldFloorVertices=0;details.traverse(o=>{if(o instanceof T.Mesh&&!(o instanceof T.InstancedMesh)){const p=o.geometry.getAttribute('position');for(let i=0;i<p.count;i++){const v=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(o.matrixWorld);if(Math.abs(v.x)<64&&Math.abs(v.z)<64&&(Math.abs(v.y-.06)<1e-5||Math.abs(v.y-.07)<1e-5))oldFloorVertices++;}}});assert.equal(oldFloorVertices,0);});
test('beach decorations no longer include almost coplanar boardwalk overlays',()=>{const details=new ArenaDetails('beach');details.updateMatrixWorld(true);let overlays=0;details.traverse(o=>{if(o instanceof T.Mesh){const p=o.geometry.getAttribute('position');for(let i=0;i<p.count;i++){const v=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(o.matrixWorld);if(Math.abs(v.y-3.06)<1e-5||Math.abs(v.y-3.045)<1e-5)overlays++;}}});assert.equal(overlays,0);});

test('rotating stadium preview fits every arena corner without a close-up depth range',()=>{const bounds=new T.Box3(new T.Vector3(-210,-12,-210),new T.Vector3(210,56,210));for(const angle of [.49,.64,.79]){const cam=new T.PerspectiveCamera(37,1.5,.1,900);cam.position.set(Math.sin(angle)*432,328,Math.cos(angle)*432);cam.lookAt(0,0,0);const range=previewDepthRange(cam,bounds);assert.ok(range.near>150);assert.ok(range.far/range.near<6);for(const x of [-210,210])for(const y of [-12,56])for(const z of [-210,210]){const depth=-new T.Vector3(x,y,z).applyMatrix4(cam.matrixWorldInverse).z;assert.ok(depth>range.near&&depth<range.far);}}});
test('fitted preview depth keeps turf and its foundation separated across the far pitch',()=>{const cam=new T.PerspectiveCamera(37,1.5,.1,900);cam.position.set(300,328,310);cam.lookAt(0,0,0);const bounds=new T.Box3(new T.Vector3(-210,-12,-210),new T.Vector3(210,56,210)),range=previewDepthRange(cam,bounds);cam.near=range.near;cam.far=range.far;cam.updateProjectionMatrix();for(const x of [-128,0,128])for(const z of [-128,0,128]){const turf=new T.Vector3(x,0,z).project(cam).z,base=new T.Vector3(x,-.2,z).project(cam).z;assert.ok(Math.abs(turf-base)*(2**24-1)/2>500);}});

test('blocked bots commit to reversing and escape a castle wall without teleporting',()=>{for(const speedClass of [50,100,150] as const){const s=createState({...config,arena:'castle',speedClass});s.phase='playing';s.boxes.forEach(b=>b.respawn=100);const k=s.karts[1];k.bot=true;k.x=81.9;k.z=88;k.y=0;k.angle=Math.PI/2;k.speed=0;k.vx=0;k.vz=0;k.stuck=1;s.karts[0].x=105;s.karts[0].z=88;const start={x:k.x,z:k.z};assert.equal(botInput(s,k).gas,-1);for(let i=0;i<30;i++)drive(s,k,botInput(s,k),1/60);assert.equal(botInput(s,k).gas,-1,'reverse must persist after making progress');for(let i=0;i<180;i++)drive(s,k,botInput(s,k),1/60);assert.ok(Math.hypot(k.x-start.x,k.z-start.z)>8,'must leave the blocked position at '+speedClass);assert.ok(k.y>=0);}});



test('automatic driving controllers handle empty browser slots and reserve explicit assignments',()=>{const saved=globalThis.addEventListener,descriptor=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const make=(index:number)=>({index,connected:true,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[0,0]});const first=make(2),second=make(4);let connected:any[]=[null,null,first,null,second];Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>connected});try{const c=new Controls();c.active=true;first.buttons[7].value=1;first.axes[0]=.8;assert.equal(c.gamepad(0)?.index,2);assert.equal(c.gamepad(1)?.index,4);assert.equal(c.read(0).gas,1);assert.ok(c.read(0).steer<-.5);assert.equal(c.read(1).gas,0);c.pads[1]=2;assert.equal(c.gamepad(0)?.index,4);assert.equal(c.gamepad(1)?.index,2);assert.equal(c.read(1).gas,1);connected=[null,null,null,null,second];assert.equal(c.gamepad(1),undefined);assert.equal(c.gamepad(0)?.index,4);}finally{globalThis.addEventListener=saved;if(descriptor)Object.defineProperty(navigator,'getGamepads',descriptor);else Reflect.deleteProperty(navigator,'getGamepads');}});

test('menu handoff blocks held actions without blocking steering or throttle',()=>{const saved=globalThis.addEventListener,descriptor=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const pad={index:1,connected:true,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[.7,.35]};Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[null,pad]});try{const c=new Controls();c.active=true;pad.buttons[0].pressed=true;pad.buttons[7].value=1;c.blockPads();let input=c.read(0);assert.equal(input.gas,1);assert.ok(input.steer<0);assert.equal(input.hop,false);pad.buttons[1].pressed=true;assert.equal(c.read(0).fire,true);pad.buttons[0].pressed=false;c.read(0);pad.buttons[0].pressed=true;assert.equal(c.read(0).hop,true);assert.equal(c.padLocks.size,0);c.active=false;assert.deepEqual(c.read(0),idle());}finally{globalThis.addEventListener=saved;if(descriptor)Object.defineProperty(navigator,'getGamepads',descriptor);else Reflect.deleteProperty(navigator,'getGamepads');}});

test('keyboard-only slots do not consume controllers and explicit reassignment stays unique',()=>{const saved=globalThis.addEventListener,descriptor=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const pad={index:2,connected:true,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[0,0]};Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[null,null,pad]});try{const c=new Controls();c.assignPad(0,-2);assert.equal(c.gamepad(0),undefined);assert.equal(c.gamepad(1)?.index,2);c.assignPad(0,2);assert.equal(c.gamepad(0)?.index,2);assert.equal(c.gamepad(1),undefined);c.assignPad(1,2);assert.equal(c.pads[0],-1);assert.equal(c.gamepad(0),undefined);assert.equal(c.gamepad(1)?.index,2);}finally{globalThis.addEventListener=saved;if(descriptor)Object.defineProperty(navigator,'getGamepads',descriptor);else Reflect.deleteProperty(navigator,'getGamepads');}});

function customMusicHarness(){const media={paused:true,src:'',preload:'',onended:null as null|(()=>void),onerror:null as null|(()=>void),plays:0,pauses:0,loads:0,load(){this.loads++;},pause(){this.paused=true;this.pauses++;},play(){this.paused=false;this.plays++;return Promise.resolve();}},connections:unknown[]=[];const player=new ArenaMusic(()=>media as unknown as HTMLAudioElement),destination={} as AudioNode,context={createMediaElementSource:()=>({connect:(node:unknown)=>connections.push(node)})} as unknown as AudioContext;return {media,player,context,destination,connections};}
test('arena MP3s rotate, loop, pause and use the music volume bus; empty maps fall back',async()=>{const {media,player,context,destination,connections}=customMusicHarness();player.tracks.beach=[{title:'Waves',url:'/music/beach/waves.mp3'},{title:'Sunset',url:'/music/beach/sunset.mp3'}];assert.equal(player.update('castle',true,context,destination),null);assert.equal(player.update('beach',true,context,destination),'Waves');await Promise.resolve();assert.equal(media.src,'/music/beach/waves.mp3');assert.deepEqual(connections,[destination]);player.update('beach',false,context,destination);assert.equal(media.paused,true);player.update('beach',true,context,destination);await Promise.resolve();assert.equal(media.loads,1,'resume keeps playback position');media.onended!();assert.equal(player.update('beach',true,context,destination),'Sunset');await Promise.resolve();media.onended!();assert.equal(player.update('beach',true,context,destination),'Waves');await Promise.resolve();assert.equal(player.update('castle',true,context,destination),null);assert.equal(media.paused,true);});
test('broken MP3s skip to the next file then fall back without retrying forever',async()=>{const {media,player,context,destination}=customMusicHarness();player.tracks.beach=[{title:'Broken',url:'/music/beach/a.mp3'},{title:'Good',url:'/music/beach/b.mp3'}];player.update('beach',true,context,destination);await Promise.resolve();media.onerror!();assert.equal(player.update('beach',true,context,destination),'Good');await Promise.resolve();media.onerror!();assert.equal(player.update('beach',true,context,destination),null);assert.equal(media.paused,true);assert.equal(player.failed.size,2);});
test('blocked autoplay waits for user interaction rather than discarding a valid MP3',async()=>{const {media,player,context,destination}=customMusicHarness();player.tracks.beach=[{title:'Waves',url:'/music/beach/waves.mp3'}];media.play=()=>{media.plays++;return Promise.reject({name:'NotAllowedError'});};player.update('beach',true,context,destination);await Promise.resolve();await Promise.resolve();assert.equal(player.blocked,true);player.update('beach',true,context,destination);assert.equal(media.plays,1);assert.equal(player.failed.size,0);player.unlock();media.play=()=>{media.paused=false;media.plays++;return Promise.resolve();};player.update('beach',true,context,destination);await Promise.resolve();assert.equal(media.paused,false);});


test('music scenes distinguish title, arena and pause without changing the selected map',()=>{assert.equal(selectMusicScene(false,false,'castle'),'title');assert.equal(selectMusicScene(true,false,'castle'),'castle');assert.equal(selectMusicScene(true,true,'castle'),'pause');assert.equal(selectMusicScene(false,true,'beach'),'title');});
test('title and pause MP3s switch with gameplay and empty menu folders synthesize a fallback',async()=>{const {player,media,context,destination}=customMusicHarness();Object.assign(context,{currentTime:1,destination});const sound=new Sound();sound.ctx=context;sound.customMusic=player;const notes:number[]=[];sound.musicNote=(frequency:number)=>{notes.push(frequency);};player.tracks.title=[{title:'Menu',url:'/music/title/menu.mp3'}];player.tracks.pause=[{title:'Break',url:'/music/pause/break.mp3'}];player.tracks.castle=[{title:'Castle',url:'/music/castle/castle.mp3'}];for(const [scene,title] of [['title','Menu'],['castle','Castle'],['pause','Break'],['castle','Castle']] as const){sound.updateMusic('castle',true,false,scene);await Promise.resolve();assert.equal(sound.currentTrack,title+' · MP3');assert.equal(player.arena,scene);assert.equal(media.paused,false);}player.tracks.title=[];sound.updateMusic('castle',true,false,'title');assert.ok(sound.currentTrack.startsWith('Title · '));assert.ok(notes.length>0);assert.equal(media.paused,true);});


test('combat feedback identifies self hits, shield blocks, turbo rams and environmental damage',()=>{const s=match(),victim=s.karts[0],attacker=s.karts[1];const event={id:1,type:'hit' as const,x:0,y:0,z:0,player:0,source:0,cause:'mine' as const,blocked:false};assert.equal(combatMessage(event,0,s.karts)?.text,'Your own mine!');assert.equal(combatMessage({...event,cause:'bolt'},0,s.karts)?.text,'Your own ricochet!');assert.equal(combatMessage({...event,blocked:true},0,s.karts)?.text,'Shield blocked your own mine!');assert.equal(combatMessage({...event,source:1,cause:'ram'},1,s.karts)?.text,'Hit '+victim.name+' with Turbo ram!');assert.equal(combatMessage({...event,source:1,cause:'ram',blocked:true},1,s.karts)?.positive,false);assert.equal(combatMessage({...event,source:1,cause:'ram'},0,s.karts)?.text,'Turbo ram from '+attacker.name+'!');assert.equal(combatMessage({...event,cause:'ring'},0,s.karts)?.text,'Outside the danger ring!');assert.equal(combatMessage(event,3,s.karts),null);victim.balloons=0;assert.equal(combatMessage({...event,remaining:2},0,s.karts)?.text,'Your own mine!');});
test('incoming hit direction respects chase-camera orientation and suppresses unknown directions',()=>{const event={id:1,type:'hit' as const,x:0,y:0,z:0,player:0,fromX:0,fromZ:10};assert.equal(hitDirection(event,0),0);assert.equal(hitDirection({...event,fromX:10,fromZ:0},0),-90);assert.equal(hitDirection({...event,fromX:-10,fromZ:0},0),90);assert.equal(hitDirection(event,Math.PI/2),90);assert.equal(Math.abs(hitDirection({...event,fromZ:-10},0)!),180);assert.equal(hitDirection({...event,fromZ:0},0),null);assert.equal(hitDirection({...event,fromX:undefined},0),null);assert.equal(viewportStyle(1,2,true),'left:50%;top:0%;width:50%;height:100%');assert.equal(viewportStyle(2,3,true),'left:0%;top:50%;width:50%;height:50%');});
test('hit events carry damage cause and impact direction through shield and successful damage',()=>{const s=match(),k=s.karts[0];k.shield=2;damage(s,k,1,{cause:'ram',fromX:10,fromZ:0});let event=s.events.find(e=>e.type==='hit')!;assert.equal(event.cause,'ram');assert.equal(event.blocked,true);assert.equal(event.remaining,3);assert.equal(event.fromX,10);k.inv=0;damage(s,k,1,{cause:'bolt',fromX:-10,fromZ:0});event=s.events.filter(e=>e.type==='hit').at(-1)!;assert.equal(event.cause,'bolt');assert.equal(event.blocked,false);assert.equal(event.remaining,2);assert.equal(event.fromX,-10);});
test('self ricochets require both a rebound and expired launch protection and never award self credit',()=>{for(const [bounces,age,expected] of [[0,1,3],[1,.1,3],[1,.8,2]]){const s=podState(),p=pod(0,-2,0);s.karts[0].x=0;s.karts[0].z=0;p.bounces=bounces;p.age=age;advanceRicochet(s,p,.1);assert.equal(s.karts[0].balloons,expected);assert.equal(s.karts[0].hits,0);assert.equal(s.karts[0].kills,0);if(expected===2){const event=s.events.find(e=>e.type==='hit')!;assert.equal(event.cause,'bolt');assert.equal(event.source,event.player);assert.equal(combatMessage(event,0,s.karts)?.text,'Your own ricochet!');assert.ok(event.fromZ!<event.z);}}});


test('Chaos Cam holds six-second shots, selects living drivers and resets cleanly',()=>{const s=createState({...config,humans:3,bots:2});s.phase='playing';const director=new ChaosDirector();director.update(s);const first=director.targetId;assert.equal(director.focus(s).x,s.karts[first!].x);assert.equal(director.focus(s).z,s.karts[first!].z);assert.ok(s.karts.some(k=>k.id===first&&k.balloons>0));for(const tick of [1,60,180,359]){s.tick=tick;s.karts.forEach(k=>k.boost=k.id===first?0:2);director.update(s);assert.equal(director.targetId,first);}s.tick=360;director.update(s);assert.notEqual(director.targetId,first);const next=director.targetId!;s.karts[next].balloons=0;s.tick=361;director.update(s);assert.notEqual(director.targetId,next);assert.ok(s.karts[director.targetId!].balloons>0);director.reset();assert.equal(director.targetId,null);assert.equal(director.lastEvent,0);});
test('broadcast captions attribute eliminations, show goals and do not replay stale events',()=>{const s=match();damage(s,s.karts[0],1);s.karts[0].inv=0;damage(s,s.karts[0],1);s.karts[0].inv=0;damage(s,s.karts[0],1);const event=s.events.find(e=>e.type==='eliminated')!;assert.equal(event.source,1);assert.equal(broadcastCaption(s,event),s.karts[1].name+' eliminated '+s.karts[0].name+'!');const director=new ChaosDirector();director.update(s);const until=director.captionUntil;s.tick=60;director.update(s);assert.equal(director.captionUntil,until);assert.equal(broadcastCaption(s,{...event,type:'goal',team:'blue'}),'BLUE GOAL!');assert.equal(broadcastCaption(s,{...event,type:'hit',source:0,cause:'bolt'}),s.karts[0].name+' caught their own ricochet!');});
test('stadium broadcasts can follow the ball and show championship points without creating a fourth player',()=>{const s=createState({...config,arena:'stadium',humans:3,bots:2,championship:true});s.phase='playing';s.ball!.vx=8;const director=new ChaosDirector();director.update(s);assert.equal(director.ball,true);assert.equal(director.focus(s).name,'FOLLOWING THE BALL');const size=s.karts.length;s.karts[0].balloons=1;s.karts[1].balloons=3;s.karts[1].kills=2;s.championship!.standings.find(row=>row.id===1)!.points=10;const rows=broadcastStandings(s);assert.equal(rows[0].id,1);assert.equal(rows[0].points,10);assert.equal(s.config.humans,3);assert.equal(s.karts.length,size);});



test('round stats count actual shots, enemy balloon hits, turbo rams and self losses only once',()=>{const s=match(),a=s.karts[0],b=s.karts[1];assert.equal(projectileAccuracy(a),null);a.item='bolt';useItem(s,a);assert.equal(a.stats!.projectilesFired,1);b.shield=1;damage(s,b,a.id,{cause:'bolt'});assert.equal(a.stats!.projectileHits,0);b.inv=0;damage(s,b,a.id,{cause:'bolt'});assert.equal(a.stats!.projectileHits,1);assert.equal(projectileAccuracy(a),100);damage(s,b,a.id,{cause:'bolt'});assert.equal(a.stats!.projectileHits,1,'invulnerability prevents duplicate hit credit');b.inv=0;damage(s,b,a.id,{cause:'ram'});assert.equal(a.stats!.turboRams,1);assert.equal(a.hits,2);a.inv=0;damage(s,a,a.id,{cause:'mine'});assert.equal(a.stats!.selfLosses,1);assert.equal(a.hits,2,'self damage cannot credit enemy hits');a.inv=0;damage(s,a,a.id,{cause:'timeout'});assert.equal(a.stats!.selfLosses,1);a.item='shield';useItem(s,a);assert.equal(a.stats!.projectilesFired,1);const next=nextRoundState(s);assert.deepEqual(next.karts[0].stats,newRoundStats());});
