test('landing suspension compresses, settles and stays bounded across frame rates',()=>{for(const dt of [1/120,1/60,1/30,.2]){const spring={offset:0,velocity:0};stepSuspension(spring,dt,-1.2);assert.ok(spring.offset<0);for(let i=0;i<240;i++){stepSuspension(spring,dt);assert.ok(Math.abs(spring.offset)<=.121);}assert.ok(Math.abs(spring.offset)<.002);assert.ok(Number.isFinite(spring.velocity));}});
test('all drivers have body paint, matte tires, glancing pupils and bounded landing reactions in both styles',()=>{for(const trial of [false,true])for(let id=0;id<8;id++){const model=createKart(id,trial);let physical=0,rubber=0,pupils=0;model.traverse(object=>{if(object instanceof T.Mesh&&!Array.isArray(object.material)){if(object.material instanceof T.MeshPhysicalMaterial&&object.material.clearcoat>.5)physical++;if(object.material instanceof T.MeshStandardMaterial&&object.material.roughness>.95)rubber++;}if(object.name==='pupil')pupils++;});assert.ok(physical>0);assert.ok(rubber>0);assert.equal(pupils,2);assert.ok(model.getObjectByName('contactShadow'));model.userData.grounded=false;animateKart(model,{speed:10,steering:.5,drift:0,boost:0,vy:-9},1/60,1);model.userData.grounded=true;model.userData.lookYaw=.35;model.userData.emoteKind='pickup';model.userData.emoteUntil=2;animateKart(model,{speed:10,steering:.5,drift:0,boost:0,vy:0},1/60,1.1);assert.ok(model.getObjectByName('chassis')!.position.y<0);assert.ok(Math.abs(model.getObjectByName('head')!.rotation.y)<.6);model.userData.reduced=true;animateKart(model,{speed:0,steering:0,drift:0,boost:0,vy:0},1/60,2);assert.equal(model.userData.suspension.offset,0);}});
