test('Fortress ramps have disjoint footprints and clear upper bridge lanes',()=>{const bounds=(r:typeof FORT_RAMPS[number])=>r.axis==='x'?{x:(r.from+r.to)/2,z:r.cross,w:Math.abs(r.to-r.from),d:r.width}:{x:r.cross,z:(r.from+r.to)/2,w:r.width,d:Math.abs(r.to-r.from)};for(let i=0;i<FORT_RAMPS.length;i++){const a=bounds(FORT_RAMPS[i]);for(let j=i+1;j<FORT_RAMPS.length;j++){const b=bounds(FORT_RAMPS[j]);assert.ok(Math.abs(a.x-b.x)>=(a.w+b.w)/2||Math.abs(a.z-b.z)>=(a.d+b.d)/2);}for(const bridge of FORT_BRIDGES.filter(b=>b.y===FORT_RAMPS[i].top)){const gapX=Math.abs(a.x-bridge.x)-(a.w+bridge.width)/2,gapZ=Math.abs(a.z-bridge.z)-(a.d+bridge.depth)/2;assert.ok(Math.max(gapX,gapZ)>=1,'bridge must leave at least 2.4m of clearance from ramp');}}});
test('Fortress ramps remain driveable across their full usable width at every speed',()=>{for(const cc of [50,100,150] as const)for(const r of FORT_RAMPS)for(const offset of [-r.width/2+1,0,r.width/2-1]){const s=createState({...config,speedClass:cc}),k=s.karts[0],scale=ARENA_SCALE.fortress,sign=Math.sign(r.to-r.from);s.phase='playing';k.x=(r.axis==='x'?r.from:r.cross+offset)*scale;k.z=(r.axis==='z'?r.from:r.cross+offset)*scale;k.y=r.bottom*ARENA_HEIGHT.fortress;k.angle=r.axis==='x'?sign*Math.PI/2:sign>0?0:Math.PI;let arrived=false;for(let i=0;i<240;i++){drive(s,k,{...idle(),gas:1},1/60);assert.ok(k.y>=r.bottom*ARENA_HEIGHT.fortress-.1,'kart falls through ramp');const along=(r.axis==='x'?k.x:k.z)/scale;if((along-r.to)*sign>.2){assert.equal(k.y,r.top*ARENA_HEIGHT.fortress);arrived=true;break;}}assert.ok(arrived,'kart failed to reach landing');}});

test('each arena load picks one random MP3, including same-map rematches, while pauses preserve the choice',async()=>{const h=customMusicHarness(),rolls=[.99,0];let calls=0;const player=new ArenaMusic(()=>h.media as unknown as HTMLAudioElement,()=>{calls++;return rolls.shift()??0;});player.tracks.beach=[{title:'A',url:'/music/beach/a.mp3'},{title:'B',url:'/music/beach/b.mp3'},{title:'C',url:'/music/beach/c.mp3'}];player.startArena('beach');assert.equal(player.update('beach',true,h.context,h.destination),'C');await Promise.resolve();for(let i=0;i<10;i++)player.update('beach',true,h.context,h.destination);assert.equal(calls,1);player.update('beach',false,h.context,h.destination);player.update('pause',true,h.context,h.destination);assert.equal(player.update('beach',true,h.context,h.destination),'C');assert.equal(calls,1);h.media.onended!();assert.equal(player.update('beach',true,h.context,h.destination),'A');player.next('beach');assert.equal(player.update('beach',true,h.context,h.destination),'B');player.startArena('beach');assert.equal(player.update('beach',true,h.context,h.destination),'A');assert.equal(calls,2);});
