test('intro camera sweeps gently, frames portrait views and remains still for reduced motion',()=>{for(const arena of ARENA_IDS){const a=introPose(arena,ROUND_COUNTDOWN),b=introPose(arena,3.1),still=introPose(arena,3.1,true),start=introPose(arena,ROUND_COUNTDOWN,true);assert.notEqual(a.x,b.x);assert.equal(still.x,start.x);assert.ok(Number.isFinite(a.x+a.y+a.z));assert.ok(introPose(arena,5,false,.6).y>a.y);}});
test('volcano and firework cues avoid sharp high-frequency noise layers',()=>{const sound=Object.create(Sound.prototype),calls:any[]=[];sound.tone=(...a:any[])=>calls.push(['tone',...a]);sound.filteredNoise=(...a:any[])=>calls.push(['noise',...a]);for(const effect of ['volcanocharge','volcano','volcanoimpact'])sound.effect(effect);assert.ok(calls.filter(c=>c[0]==='noise').every(c=>c[2]<=300&&c[4]!==true));assert.ok(calls.filter(c=>c[0]==='tone').every(c=>c[3]!=='sawtooth'&&c[3]!=='square'));});

test('shield hum follows active shields and the watched driver, fading with distance',()=>{const k={id:1,x:0,y:0,z:0,shield:5,balloons:3};assert.equal(shieldHumLevel([k],[k],true),1);assert.equal(shieldHumLevel([k],[k],false),0);assert.equal(shieldHumLevel([{...k,shield:0}],[k],true),0);assert.equal(shieldHumLevel([{...k,balloons:0}],[k],true),0);assert.ok(shieldHumLevel([k],[{...k,id:2,x:10}],true)>0);assert.equal(shieldHumLevel([k],[{...k,id:2,x:80}],true),0);assert.equal(shieldHumLevel([k],[undefined],true),0);});

import {FORTRESS_PROPS} from '../src/fortressProps';
